def count_pairs(A, B, W):
    K = 0
    for m in A:
        for n in B:
            if abs(m - n) <= W:
                K += 1
    return K

def solve_consecutive(Na, Nb, W):
    max_K = 0
    # Try different offsets x for B = {x+1, ..., x+Nb}
    # A = {1, ..., Na}
    A = set(range(1, Na + 1))
    for x in range(-Nb - W, Na + W):
        B = set(range(x + 1, x + Nb + 1))
        K = count_pairs(A, B, W)
        if K > max_K:
            max_K = K
    return max_K

print(solve_consecutive(2000, 2016, 1000))

def solve_consecutive_fast(Na, Nb, W):
    max_K = 0
    A_start, A_end = 1, Na
    for x in range(-Nb - W, Na + W):
        B_start, B_end = x + 1, x + Nb
        K = 0
        for m in range(A_start, A_end + 1):
            win_start, win_end = m - W, m + W
            inter_start = max(B_start, win_start)
            inter_end = min(B_end, win_end)
            if inter_start <= inter_end:
                K += inter_end - inter_start + 1
        if K > max_K:
            max_K = K
    return max_K

print(solve_consecutive_fast(2000, 2016, 1000))

